ALTER TABLE forecast.forecasts SET (timescaledb.enable_columnstore, timescaledb.segmentby = 'series_id', timescaledb.orderby = 'target_time DESC, available_at DESC');

CALL add_columnstore_policy('forecast.forecasts', after => INTERVAL '7 days', if_not_exists => true);

