ALTER TABLE forecast.actuals SET (timescaledb.enable_columnstore, timescaledb.segmentby = 'series_id', timescaledb.orderby = 'target_time DESC, available_at DESC');

CALL add_columnstore_policy('forecast.actuals', after => INTERVAL '7 days', if_not_exists => true);

CREATE OR REPLACE FUNCTION forecast.data_quality_sweep(scan_window interval DEFAULT '2 days')
RETURNS TABLE(issue text, table_name text, series_id bigint, n bigint)
LANGUAGE sql STABLE AS $$
    SELECT 'orphan_series'::text, 'forecasts'::text, p.series_id, count(*)
    FROM forecast.forecasts p LEFT JOIN forecast.series sr USING (series_id)
    WHERE p.recorded_at > now() - scan_window AND sr.series_id IS NULL
    GROUP BY p.series_id
    UNION ALL
    SELECT 'off_grid_target_time', 'forecasts', p.series_id, count(*)
    FROM forecast.forecasts p JOIN forecast.series sr USING (series_id)
    WHERE p.recorded_at > now() - scan_window
      AND sr.sample_interval > interval '0'
      AND sr.sample_interval < interval '28 days'
      AND time_bucket(sr.sample_interval, p.target_time) <> p.target_time
    GROUP BY p.series_id
    UNION ALL
    SELECT 'orphan_series'::text, 'predictors'::text, p.series_id, count(*)
    FROM forecast.predictors p LEFT JOIN forecast.series sr USING (series_id)
    WHERE p.recorded_at > now() - scan_window AND sr.series_id IS NULL
    GROUP BY p.series_id
    UNION ALL
    SELECT 'off_grid_target_time', 'predictors', p.series_id, count(*)
    FROM forecast.predictors p JOIN forecast.series sr USING (series_id)
    WHERE p.recorded_at > now() - scan_window
      AND sr.sample_interval > interval '0'
      AND sr.sample_interval < interval '28 days'
      AND time_bucket(sr.sample_interval, p.target_time) <> p.target_time
    GROUP BY p.series_id
    UNION ALL
    SELECT 'orphan_series'::text, 'actuals'::text, p.series_id, count(*)
    FROM forecast.actuals p LEFT JOIN forecast.series sr USING (series_id)
    WHERE p.recorded_at > now() - scan_window AND sr.series_id IS NULL
    GROUP BY p.series_id
    UNION ALL
    SELECT 'off_grid_target_time', 'actuals', p.series_id, count(*)
    FROM forecast.actuals p JOIN forecast.series sr USING (series_id)
    WHERE p.recorded_at > now() - scan_window
      AND sr.sample_interval > interval '0'
      AND sr.sample_interval < interval '28 days'
      AND time_bucket(sr.sample_interval, p.target_time) <> p.target_time
    GROUP BY p.series_id
$$;
